//! Complete required-list metadata uses the SAME discovered all-registration factory.
//! Validation results grant no captured configuration/source/executed-policy authority.
use crate::{required_scope_policy::{self as policy,Requirement},scopes::Scopes,key_policy_control::{self as kc,Control}};
pub use crate::allow_registry_fields::{SYS_SCOPE_GROUP as SYS_GROUP,SYS_SCOPE_LISTS as SYS_LISTS};
pub fn sys_name<C:Control>(module:&str,c:&mut C)->Result<String,C::Error>{crate::allow_registry_fields::scope_sys_name(module,c)}
pub(crate) fn visit_sys<C:Control>(module:&str,c:&mut C,visit:&mut dyn FnMut(Requirement<'_>,&mut C)->Result<(),C::Error>)->Result<(),C::Error>{let name=sys_name(module,c)?;visit(Requirement{name:&name,group:SYS_GROUP,lists:SYS_LISTS},c)?;c.checkpoint()}
/// Private construction occurs only after the unique complete metadata traversal
/// and every original list question succeeds. No partial Registry/bool is accepted.
pub struct CompleteRequiredScopeValidation{problems:Vec<String>}
impl CompleteRequiredScopeValidation{pub fn problems(&self)->&[String]{&self.problems}pub fn into_problems(self)->Vec<String>{self.problems}}
pub fn validate_complete_registry_scopes<C:Control>(scopes:&Scopes,c:&mut C)->Result<CompleteRequiredScopeValidation,C::Error>{let mut problems=Vec::new();crate::allow_registry_fields::visit_all_scopes(c,&mut|meta,c|policy::validate_one_using(meta,scopes,c,&mut problems))?;c.checkpoint()?;Ok(CompleteRequiredScopeValidation{problems})}
#[cfg(test)]mod tests{use super::*;
 #[test]fn native_scope_metadata_equals_observed_preport_all_ordered_fields(){let mut actual=Vec::new();crate::allow_registry_fields::visit_all_scopes(&mut kc::Compatibility,&mut|meta,_|{actual.push(serde_json::json!({"name":meta.name,"group":meta.group,"lists":meta.lists}));Ok(())}).unwrap();let observed:serde_json::Value=serde_json::from_str(include_str!("../fixtures/original_policies/required_scope_registry_preport.json")).unwrap();assert_eq!(actual,observed["registered_fields"].as_array().unwrap().as_slice(),"native metadata must match independently captured ORIGINAL all-registration fields");println!("NATIVE_SCOPE_REGISTRY={}",serde_json::json!({"schema":"native-required-scope-registry-v1","engine_hash":env!("DQ_ENGINE_HASH"),"registered_fields":actual}));}
 #[cfg(feature="legacy-sem")]
 #[test]fn complete_native_scope_validation_matches_actual_full_factory_and_original_list_loop(){let registry=crate::run::registry();let mut actual=Vec::new();crate::allow_registry_fields::visit_all_scopes(&mut kc::Compatibility,&mut|meta,_|{actual.push(serde_json::json!({"name":meta.name,"group":meta.group,"lists":meta.lists}));Ok(())}).unwrap();let old:Vec<_>=registry.lints.iter().map(|lint|{let meta=lint.meta();serde_json::json!({"name":meta.name,"group":meta.group,"lists":meta.lists})}).collect();assert_eq!(actual,old,"finished factory and native full descriptor order must be identical");for scopes in [Scopes::default(),Scopes::parse("[lint.sys.lists]\nx=[]\n[lint.\"sem/handlers\".lists]\ntry_calls=[]\n").unwrap()]{let expected=policy::validate_using(registry.lints.iter().map(|lint|{let meta=lint.meta();Requirement{name:meta.name,group:meta.group,lists:meta.lists}}),&scopes,&mut kc::Compatibility).unwrap();let actual=validate_complete_registry_scopes(&scopes,&mut kc::Compatibility).unwrap();assert_eq!(actual.problems(),expected,"global list validation cannot depend on a selected-policy subset");}}
}
